package org.apache.commons.lang.text;

import java.io.*;
import java.io.Reader;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.lang.ArrayUtils;
import org.apache.commons.lang.SystemUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StrBuilder_appendFixedWidthPadLeft_TriageGen0Test {

    @Test
    public void testAppendFixedWidthPadLeft_WidthGreaterThanZero_PadNeeded() {
        StrBuilder sb = new StrBuilder();
        // obj="abc" (len 3), width=5, padChar='*' -> "***abc"
        sb.appendFixedWidthPadLeft("abc", 5, '*');
        assertEquals("***abc", sb.toString());
        assertEquals(5, sb.length());
    }

    @Test
    public void testAppendFixedWidthPadLeft_WidthGreaterThanZero_NoPadNeeded() {
        StrBuilder sb = new StrBuilder();
        // obj="abcdef" (len 6), width=4, padChar='*' -> "cdef" (takes last 4 chars)
        sb.appendFixedWidthPadLeft("abcdef", 4, '*');
        assertEquals("cdef", sb.toString());
        assertEquals(4, sb.length());
    }

    @Test
    public void testAppendFixedWidthPadLeft_WidthGreaterThanZero_ExactWidth() {
        StrBuilder sb = new StrBuilder();
        // obj="abc" (len 3), width=3, padChar='*' -> "abc"
        sb.appendFixedWidthPadLeft("abc", 3, '*');
        assertEquals("abc", sb.toString());
        assertEquals(3, sb.length());
    }

    @Test
    public void testAppendFixedWidthPadLeft_WidthZero() {
        StrBuilder sb = new StrBuilder("initial");
        // width=0: should do nothing
        sb.appendFixedWidthPadLeft("abc", 0, '*');
        assertEquals("initial", sb.toString());
        assertEquals(7, sb.length());
    }

    @Test
    public void testAppendFixedWidthPadLeft_WidthNegative() {
        StrBuilder sb = new StrBuilder("initial");
        // width < 0: should do nothing
        sb.appendFixedWidthPadLeft("abc", -1, '*');
        assertEquals("initial", sb.toString());
        assertEquals(7, sb.length());
    }

    @Test
    public void testAppendFixedWidthPadLeft_NullObject() {
        StrBuilder sb = new StrBuilder();
        String nullText = "NULL";
        sb.setNullText(nullText);
        // obj=null, width=6, padChar='0' -> "00NULL"
        sb.appendFixedWidthPadLeft(null, 6, '0');
        assertEquals("00NULL", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_IntegerObject() {
        StrBuilder sb = new StrBuilder();
        // obj=123, width=5, padChar=' ' -> "  123"
        sb.appendFixedWidthPadLeft(123, 5, ' ');
        assertEquals("  123", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_FluentInterface() {
        StrBuilder sb = new StrBuilder();
        // Ensure it returns 'this' for chaining
        StrBuilder returned = sb.appendFixedWidthPadLeft("a", 2, '0');
        assertSame(sb, returned);
        assertEquals("0a", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_LargeWidth() {
        StrBuilder sb = new StrBuilder();
        // Test capacity management
        sb.appendFixedWidthPadLeft("x", 10, 'z');
        assertEquals("zzzzzzzzzx", sb.toString());
    }
}
